<?php declare(strict_types=1);require dirname(__DIR__).'/_inc/action-bootstrap.php';$token=(string)(($_SERVER['REQUEST_METHOD']??'')==='POST'?($_POST['t']??''):($_GET['t']??''));$db=Database::platform();$service=$db?new SavedNumbersService($db):null;$row=$service?$service->findConfirm($token):null;$kept=false;if(($_SERVER['REQUEST_METHOD']??'')==='POST'&&validPost()&&$row)$kept=$service->keep($token);toolsStart('Keep saved numbers | Ittai','Keep your saved calculator numbers.','https://ittai.ca/tools/keep/','Keep saved numbers');?><header class="hero"><h1><?= $kept?'Kept':'Keep my saved numbers?'?></h1></header><?php if($kept):?><p>Your saved numbers will be kept.</p><?php elseif($row):?><form method="post"><input type="hidden" name="csrf" value="<?=h($_SESSION['tool_csrf'])?>"><input type="hidden" name="t" value="<?=h($token)?>"><button type="submit">Keep my saved numbers</button></form><?php else:?><p>This link is invalid or has expired.</p><?php endif;toolsEnd();
